            Req<AuthzExplainResponse>(HttpVerb.Post, $"/v1/authz/explain", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>A role-based permission check: does this user hold the permission through an organization role, a per-member permission, an app role, a delegated role or a group? Answered like the role layers of `POST /v1/authz/explain`, and written to the decision log (source `rbac`) with the roles the user holds, so `POST /v1/authz/what_if` can later replay it against a role change.</summary>
