            Req<AuthzRbacCheckResponse>(HttpVerb.Post, $"/v1/authz/rbac/check", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Saved what-if runs, newest first, with their summaries.</summary>
        /// <remarks>GET /v1/authz/what_if. Scope: <c>authz_decisions:read</c>.</remarks>
