    /// <summary>The <c>Changes</c> operations.</summary>
    public sealed class ChangesOperations : ResourceBase
    {
        internal ChangesOperations(AtlasTransport transport) : base(transport) { }

        /// <summary>Read the change feed: which resources changed since `after`, oldest first, in commit order. Each entry names the resource and what happened (`create`, `update`, `delete`) and carries `data`, the resource as it is now, in the same shape the webhooks use (private metadata is never included). `data` is null for a delete and for a resource that is gone by the time you read. `version` equals `seq`: drop an entry whose version is not higher than the one you hold for that resource. Changes to fields that only record activity (last sign-in, last use of a key, counters) do not create entries. 410 `RESYNC_REQUIRED` when `after` is older than `retention_floor_seq`: read a snapshot instead. Entries are kept 30 days by default (`auth_config.changeFeed.retentionDays`). Needs an API key that is not limited to some organizations.</summary>
        /// <remarks>GET /v1/changes. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesListResponse> ListAsync(ChangesListQuery? query = null, CancellationToken cancellationToken = default) =>
            Req<ChangesListResponse>(HttpVerb.Get, $"/v1/changes", query: query?.ToQuery(), cancellationToken: cancellationToken);

        /// <summary>Every named consumer of the instance, across API keys: its name, the key that owns it (`key_id`), the position it acknowledged, when that last moved, and its lag behind the feed head. Behind-most first, up to 200. Use it to spot a reader that stopped, before its position falls behind the retention floor. Needs an API key that is not limited to some organizations.</summary>
        /// <remarks>GET /v1/changes/consumers. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesListConsumersResponse> ListConsumersAsync(ChangesListConsumersQuery? query = null, CancellationToken cancellationToken = default) =>
            Req<ChangesListConsumersResponse>(HttpVerb.Get, $"/v1/changes/consumers", query: query?.ToQuery(), cancellationToken: cancellationToken);

        /// <summary>Where a named consumer has read up to, and how far behind it is. The position is held on the server so a restarted reader resumes where it left off. Positions belong to the API key that wrote them.</summary>
        /// <remarks>GET /v1/changes/consumers/{name}. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesGetConsumerResponse> GetConsumerAsync(string name, CancellationToken cancellationToken = default) =>
            Req<ChangesGetConsumerResponse>(HttpVerb.Get, $"/v1/changes/consumers/{Enc(name)}", cancellationToken: cancellationToken);

        /// <summary>Acknowledge that a consumer has processed the feed up to `seq`. The position only moves forward: a lower or equal `seq` is accepted and changes nothing, so a retry is safe. A `seq` beyond `head_seq` is a 400. Consumer name: 1-64 characters from letters, digits, dot, dash and underscore. Names belong to the API key that uses them, so two keys can use the same name without sharing a position.</summary>
        /// <remarks>PUT /v1/changes/consumers/{name}/ack. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesGetConsumerResponse> SetConsumersAckAsync(string name, ChangesSetConsumersAckBody body, CancellationToken cancellationToken = default) =>
            Req<ChangesGetConsumerResponse>(HttpVerb.Put, $"/v1/changes/consumers/{Enc(name)}/ack", body: body, cancellationToken: cancellationToken);

        /// <summary>Acknowledge that a consumer has processed the feed up to `seq`. The position only moves forward: a lower or equal `seq` is accepted and changes nothing, so a retry is safe. A `seq` beyond `head_seq` is a 400. Consumer name: 1-64 characters from letters, digits, dot, dash and underscore. Names belong to the API key that uses them, so two keys can use the same name without sharing a position.</summary>
        /// <remarks>PUT /v1/changes/consumers/{name}/ack. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesGetConsumerResponse> SetConsumersAckAsync(string name, ChangesSetConsumersAckBody body, string idempotencyKey, CancellationToken cancellationToken = default) =>
            Req<ChangesGetConsumerResponse>(HttpVerb.Put, $"/v1/changes/consumers/{Enc(name)}/ack", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>A paginated, full list of the live resources of one type, in id order, pinned to the feed position it was taken at. Walk every page, then follow `GET /v1/changes?after={snapshot_seq}`: no change between the snapshot and the feed is missed, and an entry already reflected in a page is applied again harmlessly (apply by version). `next_cursor` carries the pin, so every page of one walk reports the same `snapshot_seq`. 410 `RESYNC_REQUIRED` when the pinned position has since been trimmed.</summary>
        /// <remarks>GET /v1/changes/snapshot/{resource_type}. Scope: <c>events:read</c>.</remarks>
        public Task<ChangesGetSnapshotResponse> GetSnapshotAsync(string resourceType, ChangesGetSnapshotQuery? query = null, CancellationToken cancellationToken = default) =>
            Req<ChangesGetSnapshotResponse>(HttpVerb.Get, $"/v1/changes/snapshot/{Enc(resourceType)}", query: query?.ToQuery(), cancellationToken: cancellationToken);
    }

