            Req<FgaGetSyncResponseBackfill>(HttpVerb.Post, $"/v1/fga/sync/backfill", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Remove the tuples the sync wrote (never one that existed before it) and forget them. The sync must be disabled (409 otherwise). Send `confirm: true`.</summary>
        /// <remarks>POST /v1/fga/sync/purge. Scope: <c>fga:write</c>.</remarks>
