            Req<FgaSyncPurgeResponse>(HttpVerb.Post, $"/v1/fga/sync/purge", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Sync runs, newest first: backfills, and the incremental passes that changed something.</summary>
        /// <remarks>GET /v1/fga/sync/runs. Scope: <c>fga:read</c>.</remarks>
        public Task<FgaListSyncRunsResponse> ListSyncRunsAsync(FgaListSyncRunsQuery? query = null, CancellationToken cancellationToken = default) =>
            Req<FgaListSyncRunsResponse>(HttpVerb.Get, $"/v1/fga/sync/runs", query: query?.ToQuery(), cancellationToken: cancellationToken);

        /// <summary>One sync run with its counts and any error.</summary>
        /// <remarks>GET /v1/fga/sync/runs/{id}. Scope: <c>fga:read</c>.</remarks>
        public Task<FgaGetSyncResponseBackfill> GetSyncRunAsync(string id, CancellationToken cancellationToken = default) =>
            Req<FgaGetSyncResponseBackfill>(HttpVerb.Get, $"/v1/fga/sync/runs/{Enc(id)}", cancellationToken: cancellationToken);

        /// <summary>Run an FGA test suite with no store: the model comes from `dsl` or `modules`. Returns per-test results and relation coverage. For CI.</summary>
        /// <remarks>POST /v1/fga/tests. Scope: <c>fga:read</c>.</remarks>
