            Req<GrantsConsumeResponse>(HttpVerb.Post, $"/v1/grants/{Enc(grantType)}/{Enc(id)}/consume", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Hand a lease back. What was not consumed returns to the counter. Safe to repeat.</summary>
        /// <remarks>POST /v1/grants/{grantType}/{id}/leases/{leaseId}/release. Scope: <c>machines:write</c>.</remarks>
