            Req<GrantsLeasesReleaseResponse>(HttpVerb.Post, $"/v1/grants/{Enc(grantType)}/{Enc(id)}/leases/{Enc(leaseId)}/release", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Give back all or part of one earlier consume. Never more than that consume took.</summary>
        /// <remarks>POST /v1/grants/{grantType}/{id}/refund. Scope: <c>machines:write</c>.</remarks>
        public Task<GrantsRefundResponse> RefundAsync(string grantType, string id, GrantsRefundBody body, string? idempotencyKey = null, CancellationToken cancellationToken = default) =>
            Req<GrantsRefundResponse>(HttpVerb.Post, $"/v1/grants/{Enc(grantType)}/{Enc(id)}/refund", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>The current window of every counter a grant defines, and the leases still holding an amount.</summary>
        /// <remarks>GET /v1/grants/{grantType}/{id}/usage. Scope: <c>machines:read</c>.</remarks>
        public Task<GrantsGetUsageResponse> GetUsageAsync(string grantType, string id, CancellationToken cancellationToken = default) =>
            Req<GrantsGetUsageResponse>(HttpVerb.Get, $"/v1/grants/{Enc(grantType)}/{Enc(id)}/usage", cancellationToken: cancellationToken);

        /// <summary>Read one grant of either kind, with its metadata.</summary>
        /// <remarks>GET /v1/grants/{id}. Scope: <c>grants:read</c>.</remarks>
        public Task<GrantsListResponseDataItem> GetAsync(string id, CancellationToken cancellationToken = default) =>
            Req<GrantsListResponseDataItem>(HttpVerb.Get, $"/v1/grants/{Enc(id)}", cancellationToken: cancellationToken);

