    /// <summary>The <c>Impersonations</c> operations.</summary>
    public sealed class ImpersonationsOperations : ResourceBase
    {
        internal ImpersonationsOperations(AtlasTransport transport) : base(transport) { }

        /// <summary>Start a support impersonation: a session for `user_id` whose token carries `act.sub` = `staff_user_id`. The instance policy (GET /v1/instance/impersonation_policy) decides the rules: `reason` (max 500 characters) is required unless the policy turns that off, `reason_code` must be one of the policy's codes when it lists any, the session lasts at most the policy's limit (`max_duration_seconds` can only shorten it; never more than 1 hour), and `read_only` (default from the policy) makes the session refuse every change on the Frontend API and puts `ro: true` in its token. When the policy requires approval the call answers 202 with a pending `impersonation_request`; a second staff member decides it with POST /v1/impersonations/requests/{id}/approve or /deny. Optional `require_staff_org_id` and `require_staff_mfa` apply to the staff user (and to the approver). Refused for banned, deleted and impersonation-protected users. Emits `impersonation.started` (and the older `session.impersonation_started`); the user is emailed when the policy says so and sees the session at GET /v1/client/me/staff_access. To export the trail, use GET /v1/audit_logs?action=session.impersonation_started&amp;format=jsonl.</summary>
        /// <remarks>POST /v1/impersonations. Scope: <c>impersonation:write</c>.</remarks>
        public Task CreateAsync(ImpersonationsCreateBody body, string? idempotencyKey = null, CancellationToken cancellationToken = default) =>
            ReqVoid(HttpVerb.Post, $"/v1/impersonations", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>List impersonation requests held for approval, newest first. `status`: pending, approved, denied or expired.</summary>
        /// <remarks>GET /v1/impersonations/requests. Scope: <c>impersonation:write</c>.</remarks>
        public Task<ImpersonationsListRequestsResponse> ListRequestsAsync(ImpersonationsListRequestsQuery? query = null, CancellationToken cancellationToken = default) =>
            Req<ImpersonationsListRequestsResponse>(HttpVerb.Get, $"/v1/impersonations/requests", query: query?.ToQuery(), cancellationToken: cancellationToken);

        /// <summary>Every item across every page of <c>ListRequestsAsync</c>, following <c>next_cursor</c>.</summary>
        public IAsyncEnumerable<ImpersonationsListRequestsResponseDataItem> ListRequestsAllAsync(ImpersonationsListRequestsQuery? query = null, CancellationToken cancellationToken = default) =>
            AtlasPagination.PaginateAsync<ImpersonationsListRequestsResponseDataItem>(async (_c, _ct) =>
            {
                var _q = query ?? new ImpersonationsListRequestsQuery();
                var _page = await ListRequestsAsync(_q with { StartingAfter = _c }, cancellationToken: _ct).ConfigureAwait(false);
                return new CursorPage<ImpersonationsListRequestsResponseDataItem> { Data = _page.Data ?? new List<ImpersonationsListRequestsResponseDataItem>(), HasMore = (bool?)_page.HasMore ?? false, NextCursor = _page.NextCursor };
            }, query?.StartingAfter, cancellationToken);

        /// <summary>Read one impersonation request: its status, who asked, who decided, and when it expires.</summary>
        /// <remarks>GET /v1/impersonations/requests/{id}. Scope: <c>impersonation:write</c>.</remarks>
        public Task<ImpersonationsListRequestsResponseDataItem> GetRequestAsync(string id, CancellationToken cancellationToken = default) =>
            Req<ImpersonationsListRequestsResponseDataItem>(HttpVerb.Get, $"/v1/impersonations/requests/{Enc(id)}", cancellationToken: cancellationToken);

        /// <summary>Approve a pending impersonation as a second staff member (`approver_user_id`, never the requester). Starts the session and returns it with the request; the decision and the approver are audited on the impersonated user. A request expires after 30 minutes.</summary>
        /// <remarks>POST /v1/impersonations/requests/{id}/approve. Scope: <c>impersonation:write</c>.</remarks>
        public Task RequestsApproveAsync(string id, ImpersonationsRequestsApproveBody body, string? idempotencyKey = null, CancellationToken cancellationToken = default) =>
            ReqVoid(HttpVerb.Post, $"/v1/impersonations/requests/{Enc(id)}/approve", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>Deny a pending impersonation as a second staff member. Audited; no session is created.</summary>
        /// <remarks>POST /v1/impersonations/requests/{id}/deny. Scope: <c>impersonation:write</c>.</remarks>
        public Task RequestsDenyAsync(string id, ImpersonationsRequestsApproveBody body, string? idempotencyKey = null, CancellationToken cancellationToken = default) =>
            ReqVoid(HttpVerb.Post, $"/v1/impersonations/requests/{Enc(id)}/deny", body: body, idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);

        /// <summary>End an impersonation started with POST /v1/impersonations (`id` is the returned impersonation id): revokes the session, audits it on the impersonated user and emits `impersonation.ended` (and the older `session.impersonation_ended`).</summary>
        /// <remarks>POST /v1/impersonations/{id}/end. Scope: <c>impersonation:write</c>.</remarks>
        public Task<ImpersonationsEndResponse> EndAsync(string id, string? idempotencyKey = null, CancellationToken cancellationToken = default) =>
            Req<ImpersonationsEndResponse>(HttpVerb.Post, $"/v1/impersonations/{Enc(id)}/end", idempotencyKey: idempotencyKey, cancellationToken: cancellationToken);
    }

